		$('.popup .btn_x').click(function(){
			$('body').css({"overflow": ""});
			$('.popup').addClass('hide');
		});
		$('.popup .jq_x').click(function(){
			$('body').css({"overflow": ""});
			$('.popup').addClass('hide');
